krb5_int32 prepare_kdc_request(krb5_kdc_req *request, krb5_principal *krbtgt_princ) {
    krb5_int32 ret = 0;
    krb5_data *server_name = NULL;

    if ((request->kdc_options & KDC_OPT_CANONICALIZE) == 0) {
        return 0;
    }

    server_name = krb5_principal_get_name(krb5_context, *krbtgt_princ);
    if (server_name == NULL) {
        return KRB5_ERR_NO_REALM;

    }

    if (!is_valid_fqdn(server_name->data)) {
        krb5_free_data(krb5_context, server_name);
        return KRB5_ERR_WRONG_REALM;
    }

    ret = map_fqdn_to_realm(server_name->data, &request->realm);
    if (ret != 0) {
        krb5_free_data(krb5_context, server_name);
        return ret;
    }

    request->client = *krbtgt_princ;

    return 0;
}

krb5_int32 prepare_and_reprocess_kdc_request(krb5_kdc_req *request, krb5_principal *krbtgt_princ) {
    krb5_int32 ret = 0;
    krb5_data *realm = NULL;
    krb5_principal new_server = NULL;
    krb5_boolean is_canonicalized = FALSE;

    if (!request || !krbtgt_princ)
        return KRB5KDC_ERR_BADOPTION;

    if (request->kdc_options & KDC_OPT_CANONICALIZE) {
        /* Check server principal name for valid FQDN format */
        if (krb5_principal_compare_fqdn_name(request->client, request->server)) {
            /* Map FQDN to realm */
            ret = krb5_kdc_map_fqdn_to_realm(krb5_context, request->server, &realm);
            if (ret != 0)
                return ret;

            /* Construct new cross-realm TGT principal */
            ret = krb5_build_cross_realm_principal(krb5_context, realm, krbtgt_princ, &new_server);
            if (ret != 0) {
                krb5_free_data(krb5_context, realm);
                return ret;
            }

            /* Free old server principal and replace with new one */
            krb5_free_principal(krb5_context, request->server);
            request->server = new_server;

            is_canonicalized = TRUE;
        }
    }

    if (is_canonicalized) {
        /* Modify request to reprocess with updated server principal */
        ret = krb5_kdc_reprocess_request(krb5_context, request);
        if (ret != 0)
            return ret;
    }

    /* Clean up */
    if (realm) {
        krb5_free_data(krb5_context, realm);
    }

    return 0;
}

krb5_int32 prepare_kdc_request(krb5_kdc_req *request, krb5_principal *krbtgt_princ) {
    krb5_int32 ret = 0;
    char *server_name = NULL;

    if ((request->kdc_options & KDC_OPT_CANONICALIZE) == 0) {
        return 0;
    }

    if (krb5_principal_get_name(NULL, *krbtgt_princ, &server_name) != 0) {
        return KRB5_ERR_GENERIC;
    }

    if (strstr(server_name, "fqdn")) {
        char *realm_name = NULL;
        krb5_principal new_tgt = NULL;

        if (krb5_kdc_resolve_fqdn_to_realm(NULL, server_name, &realm_name) != 0) {
            free(server_name);
            return KRB5_ERR_GENERIC;
        }

        if (krb5_build_principal_simple(NULL, &new_tgt, realm_name, "host", server_name, NULL) != 0) {
            free(server_name);
            free(realm_name);
            return KRB5_ERR_GENERIC;
        }

        if (request->client != NULL) {
            krb5_free_principal(NULL, request->client);
        }

        request->client = new_tgt;
    }

    free(server_name);
    return ret;
}

krb5_int32 prepare_and_reprocess_kdc_request(krb5_kdc_req *request, krb5_principal *krbtgt_princ) {
    krb5_int32 ret = 0;
    krb5_data *realm = NULL;
    krb5_principal new_princ = NULL;
    krb5_boolean is_canonicalized = FALSE;

    if (request->kdc_options & KDC_OPT_CANONICALIZE) {
        if (krb5_principal_get_realm(request->client, &realm) != 0) {
            return KRB5_BAD_MSIZE;
        }

        if (strcmp(realm->data, "NO_CANN") != 0) {
            if (krb5_build_principal_simple(&new_princ, realm->data, 1, "krbtgt", krbtgt_princ->realm, NULL) != 0) {
                krb5_free_data_contents(realm);
                return KRB5_KDC_PRINCIPAL_NOT_FOUND;
            }

            krb5_free_principal(request->server);
            request->server = new_princ;
            is_canonicalized = TRUE;
        }
    }

    if (is_canonicalized) {
        if (krb5_kdc_reprocess_request(request) != 0) {
            krb5_free_principal(new_princ);
            return KRB5_KDC_REPROCESS_FAILURE;
        }
    }

    return 0;
}

krb5_int32 prepare_and_reprocess_kdc_request(krb5_kdc_req *request, krb5_principal *krbtgt_princ) {
    krb5_int32 ret = 0;
    krb5_principal server_principal = NULL;
    krb5_principal cross_realm_tgt = NULL;
    krb5_data *fqdn = NULL;

    if (request->flags & KDC_OPT_CANONICALIZE) {
        server_principal = request->server;

        if (krb5_is_krbtgt_principal(server_principal)) {
            ret = krb5_build_principal_simple(kdc_context, &cross_realm_tgt,
                                              krbtgt_princ->length, krbtgt_princ->data,
                                              server_principal->realm.length, server_principal->realm.data,
                                              NULL);
            if (ret != 0) {
                goto cleanup;
            }

            ret = krb5_unparse_name(kdc_context, cross_realm_tgt, &fqdn);
            if (ret != 0) {
                goto cleanup;
            }

            krb5_free_principal(kdc_context, request->server);
            request->server = cross_realm_tgt;

            ret = krb5_kdc_reprocess_request(kdc_context, request);
        }
    }

cleanup:
    if (fqdn) {
        krb5_free_data(kdc_context, fqdn);
    }
    if (cross_realm_tgt) {
        krb5_free_principal(kdc_context, cross_realm_tgt);
    }

    return ret;
}
